"""Simulated cameras generated by the ZED SDK (``create_virtual_camera``, sl_zed 5.6.0+).

The SDK hands out both the serial number and the calibration of a simulated camera. The images
must be rendered with that calibration (see ``optics.apply_virtual_camera_optics``); the receiver
regenerates the same calibration from the serial number and takes it as the factory one.

The legacy scheme (whitelisted serial numbers with a reserved calibration file), which receivers
older than 5.6.0 can open, stays available through the ``simCameraMode`` setting.

Kit-free: ctypes only (carb is optional), so it imports in standalone Isaac Lab scripts.
"""
from __future__ import annotations

import ctypes
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Optional, Set, Tuple

MODE_SETTING = "/persistent/exts/sl.sensor.camera/simCameraMode"
MODE_VIRTUAL = "virtual"
MODE_LEGACY = "legacy"
MODES = (MODE_VIRTUAL, MODE_LEGACY)

# SIM_SERIAL_INDEX_COUNT in the SDK (sim_virtual_camera.hpp).
MAX_CAMERA_INDEX = 99999

LENS_FISHEYE = 2

_SUCCESS = 0
_INVALID_INPUT = 10

# disto[12] order, which is also the opencvPinhole attribute order
DISTO_NAMES = ("k1", "k2", "p1", "p2", "k3", "k4", "k5", "k6", "s1", "s2", "s3", "s4")


class SimIntrinsics(ctypes.Structure):
    _fields_ = [
        ("fx", ctypes.c_float),
        ("fy", ctypes.c_float),
        ("cx", ctypes.c_float),
        ("cy", ctypes.c_float),
        ("disto", ctypes.c_float * 12),
    ]


class SimCalibration(ctypes.Structure):
    """Mirror of sl::SimCalibration (SDK sl_input/sim_streamer/types_c.h, ext include/types_c.h)."""
    _fields_ = [
        ("version", ctypes.c_int),
        ("model", ctypes.c_int),
        ("lens_type", ctypes.c_int),
        ("width", ctypes.c_int),
        ("height", ctypes.c_int),
        ("left", SimIntrinsics),
        ("right", SimIntrinsics),
        # right eye extrinsics as the SDK rectification reads them: OpenCV's T = (-baseline_mm,
        # ty_mm, tz_mm) and R = (rx, ry, rz) radians map left-eye points into the right eye (IMAGE
        # frame: x right, y down, z forward). See optics.right_eye_relative_matrix.
        ("baseline_mm", ctypes.c_float),
        ("ty_mm", ctypes.c_float),
        ("tz_mm", ctypes.c_float),
        ("rx", ctypes.c_float),
        ("ry", ctypes.c_float),
        ("rz", ctypes.c_float),
        ("reserved", ctypes.c_int * 4),
    ]

    @property
    def is_fisheye(self) -> bool:
        return self.lens_type == LENS_FISHEYE

    def as_dict(self) -> dict:
        """Plain-Python copy, e.g. for Isaac Lab users building the true K matrix."""
        def eye(i):
            return {"fx": i.fx, "fy": i.fy, "cx": i.cx, "cy": i.cy, "disto": list(i.disto)}
        return {
            "model": self.model, "lens_type": self.lens_type,
            "width": self.width, "height": self.height,
            "left": eye(self.left), "right": eye(self.right),
            "baseline_mm": self.baseline_mm, "ty_mm": self.ty_mm, "tz_mm": self.tz_mm,
            "rotation_vector": [self.rx, self.ry, self.rz],
        }

    def describe(self, prefix: str = "") -> str:
        """Resolution, lens model and per-eye intrinsics + distortion as rendered, `prefix` on each line."""
        if self.is_fisheye:
            model, names, coefficients = "opencvFisheye", ("k1", "k2", "k3", "k4"), fisheye_coefficients
        else:
            model, names, coefficients = "opencvPinhole", DISTO_NAMES, lambda eye: list(eye.disto)
        lines = [f"{self.width}x{self.height} {model}"]
        for side, eye in (("left", self.left), ("right", self.right)):
            if side == "left" or self.baseline_mm > 0.0:   # a mono model's right eye is a copy of the left
                disto = " ".join(f"{name} {value:.6g}" for name, value in zip(names, coefficients(eye)))
                lines.append(f"{side:<5} fx {eye.fx:.2f} fy {eye.fy:.2f} cx {eye.cx:.2f} cy {eye.cy:.2f} | {disto}")
        return "\n".join(prefix + line for line in lines)


def fisheye_coefficients(intrinsics: SimIntrinsics):
    """OpenCV fisheye k1..k4 of an eye: the SDK stores them in disto slots 0, 1, 4, 5."""
    d = intrinsics.disto
    return [d[0], d[1], d[4], d[5]]


class SimVirtualCamera(ctypes.Structure):
    _fields_ = [
        ("serial_number", ctypes.c_int),
        ("calibration", SimCalibration),
    ]


assert ctypes.sizeof(SimCalibration) == 188, "SimCalibration layout must match the SDK"
assert ctypes.sizeof(SimVirtualCamera) == 192, "SimVirtualCamera layout must match the SDK"


class VirtualCameraError(RuntimeError):
    pass


_FALLBACK_WARNED = False


def get_mode_setting() -> str:
    """The camera mode from the persistent setting; virtual when unset or when carb is absent."""
    try:
        import carb.settings
        mode = carb.settings.get_settings().get(MODE_SETTING)
    except ImportError:
        mode = None
    return mode if mode in MODES else MODE_VIRTUAL


def get_mode() -> str:
    """The camera mode the cameras use: the setting, or legacy (warned once) when the setting is
    virtual and the bundled library cannot generate simulated cameras."""
    global _FALLBACK_WARNED
    mode = get_mode_setting()
    if mode != MODE_VIRTUAL or available():
        return mode
    if not _FALLBACK_WARNED:
        _FALLBACK_WARNED = True
        message = (f"[ZED] The bundled ZED SDK library ({_library_path().name}) cannot generate simulated "
                   f"cameras: using the legacy camera mode. Rebuild the extension to update it to 5.6.0 or newer.")
        try:
            import carb
            carb.log_warn(message)
        except ImportError:
            print(message)
    return MODE_LEGACY


def set_mode(mode: str) -> None:
    if mode not in MODES:
        raise ValueError(f"Unknown ZED camera mode '{mode}', expected one of {MODES}")
    import carb.settings
    carb.settings.get_settings().set(MODE_SETTING, mode)


# Library loading
_LIB = None
_LOAD_TRIED = False


def _library_path() -> Path:
    name = "sl_zed64.dll" if os.name == "nt" else "libsl_zed.so"
    # exts/sl.sensor.camera/bin/  (parents: camera, sensor, sl, sl.sensor.camera)
    return Path(__file__).resolve().parents[3] / "bin" / name


def _load():
    """The bundled sl_zed, the same file the streaming plugin loads (Kit preloads it on Windows)."""
    global _LIB, _LOAD_TRIED
    if _LOAD_TRIED:
        return _LIB
    _LOAD_TRIED = True
    try:
        lib = ctypes.CDLL(str(_library_path()))
    except OSError:
        return None
    if not hasattr(lib, "create_virtual_camera"):
        return None
    lib.create_virtual_camera.restype = ctypes.c_int
    lib.create_virtual_camera.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_uint, ctypes.c_int,
                                          ctypes.c_int, ctypes.POINTER(SimVirtualCamera)]
    _LIB = lib
    return _LIB


def available() -> bool:
    return _load() is not None


# Camera registry
@dataclass
class VirtualCamera:
    model_id: int
    lens_id: int
    index: int
    serial_number: int
    calibration: SimCalibration


# (SDK model id, lens id) -> camera indices in use in this process
_used_indices: Dict[Tuple[int, int], Set[int]] = {}


def acquire(model_id: int, lens_id: int, width: int, height: int,
            camera_index: Optional[int] = None) -> VirtualCamera:
    """Build a camera for this scene and reserve its index until :func:`release`.

    Args:
        model_id / lens_id: SDK MODEL code and SIM_LENS_TYPE (utils.get_sdk_model_id / get_sim_lens_type_id)
        width / height: render resolution, must be native to the model
        camera_index: None or negative picks the lowest free index for this model + lens; a given
            index always yields the same serial number and calibration

    Raises:
        VirtualCameraError: runtime too old, index taken, or the SDK rejected the request
    """
    lib = _load()
    if lib is None:
        raise VirtualCameraError(
            f"The bundled ZED SDK library ({_library_path().name}) cannot generate simulated cameras. "
            f"Update it to 5.6.0 or newer, or set the ZED camera mode to '{MODE_LEGACY}'.")

    used = _used_indices.setdefault((model_id, lens_id), set())
    if camera_index is None or camera_index < 0:
        index = next(i for i in range(MAX_CAMERA_INDEX + 1) if i not in used)
    else:
        index = int(camera_index)
        if index > MAX_CAMERA_INDEX:
            raise VirtualCameraError(f"Camera index {index} is out of range (0 to {MAX_CAMERA_INDEX}).")
        if index in used:
            raise VirtualCameraError(
                f"Camera index {index} is already used by another camera of the same model and lens.")

    out = SimVirtualCamera()
    status = lib.create_virtual_camera(model_id, lens_id, index, width, height, ctypes.byref(out))
    if status != _SUCCESS:
        hint = (" The model, lens or resolution is not supported for simulation."
                if status == _INVALID_INPUT else "")
        raise VirtualCameraError(
            f"create_virtual_camera failed (status {status}) for SDK model {model_id}, lens {lens_id}, "
            f"{width}x{height}, index {index}.{hint}")

    used.add(index)
    return VirtualCamera(model_id, lens_id, index, out.serial_number, out.calibration)


def release(camera: Optional[VirtualCamera]) -> None:
    if camera is not None:
        _used_indices.get((camera.model_id, camera.lens_id), set()).discard(camera.index)
